(* [comment removed for export] *)
Definition A_MSG_SETALL : Z := 0x36b40.     (* [comment removed for export] *)
Definition A_PROC_SETALL : Z := 0x36b20.    (* [comment removed for export] *)

Section SETALL.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis RERR : returnError_cpsF RT e_returnErrorInt.
(* [comment removed for export] *)
Hypothesis LIT1 : exists l, In (A_MSG_SETALL, l) LEPT_LITS.
Hypothesis LIT2 : exists l, In (A_PROC_SETALL, l) LEPT_LITS.

(* [comment removed for export] *)
Local Ltac memset_call RT AF FKC PFS DIN dat rs lo v :=
  at_call RT AF ltac:(cbn [ivls_client]; split; [intros zz Hzz; left; ul| exact I])
                ltac:(fun Hx => cbn [outside]; destruct Hx as [Hx1 Hx2]; pose proof (PFS _ (conj Hx1 Hx2)); cbn [outside] in Hx2; split; [lia| exact I]);
  lazymatch goal with A : ART RT ?S ?mm |- cps _ (ASTA RT ?S _ (eq (entry_st _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?mm))) _ =>
    let WRD := fresh "WRD" in let ACCD := fresh "ACCD" in
    pose proof (af_acc_live RT AF S mm dat rs A DIN) as (WRD & ACCD);
    eapply cps_seq;
    [ let MS0 := fresh "MS0" in
      pose proof (fk_asan_memset RT FKC) as MS0; unfold memset_icontractF in MS0;
      eapply MS0 with (lo := lo) (d := dat) (n := rs) (c := Z_to_bv 8 255); rt_side idtac;
      lazymatch goal with
      | |- (0 <= _ <= _) => change (2^47) with 140737488355328; lia
      | |- (0 <= _ < _) => lia
      | |- checked_dst _ _ _ _ _ _ =>
          unfold checked_dst; rewrite ?unsigned_lit by lia; split; [intros _; split; [exact ACCD| left; exists dat, rs; split; [exact DIN| lia]]|];
          split; [intros i Hi; right; right; left; exists dat, rs; split; [exact DIN| lia]| exact WRD]
      | |- Z_to_bv 64 _ = Z_to_bv 64 _ =>
          first [ reflexivity
                | f_equal; unfold zx32; rewrite ?unsigned_lit by lia; rewrite ?Z.mod_small by lia; unfold rs; lia
                | f_equal; unfold zx32; rewrite !(unsigned_lit (p_wpl v)), !(unsigned_lit (p_h v)) by lia;
                  rewrite (Z.mod_small (p_wpl v)), (Z.mod_small (p_h v)) by lia;
                  rewrite !(unsigned_lit (p_wpl v)), !(unsigned_lit (p_h v)) by lia;
                  rewrite (Z.mod_small (p_wpl v * 4)) by lia; unfold rs; lia
                | match goal with |- ?g => idtac "LEFTOVER-EQ:" g end ]
      | |- ?g => idtac "LEFTOVER:" g
      end | ] end.

Theorem pixSetAll_ok : pixSetAll_cps RT.
Proof using AF GP FKC RERR LIT1 LIT2.
Ltac finish rvv EXTRA CMCASE POBJ D1 DNZ R0 APD AGF ESP QF dat rs pix v cv usp m Σ :=
    apply cps_finish; let c := fresh "c" in let Hc := fresh "Hc" in intros c Hc; subst QF; cbv beta;
    lazymatch type of Hc with ASTA RT ?S' _ _ _ => exists S', rvv end; split; [| alg_tac];
    eapply (ASTA_conseq RT); [exact Hc|]; intros ms <-; eexists;
    split; [split; [unfold ret_st; try rewrite ESP; do 16 eexists; reflexivity| cbn [ms_fregs MS]; fs_agree_tac]|];
    split;
    [ split; [| split; assumption];
      split; [assumption|]; split; [assumption|]; split; [| assumption];
      lazymatch goal with WMx : wmono asegs m ?mf |- wmono asegs m ?mf => exact WMx | |- ?g => idtac "WMONO?" g; assumption end |];
    split; [let a := fresh "a" in let Ha := fresh "Ha" in let Ho := fresh "Ho" in intros a Ha Ho; apply AGF; split;
           [first [ exact Ha | match goal with E : rt_live RT _ = rt_live RT _ |- _ => first [rewrite E in Ha; exact Ha | rewrite <- E in Ha; exact Ha] end ]
           | exact Ho]|];
    split; [| EXTRA];
    try match goal with E : rt_live RT _ = rt_live RT Σ |- _ => rewrite E end;
    lazymatch goal with |- pix1c _ ?mf _ _ _ =>
      eapply (pix1c_keep_out (rt_live RT Σ) (rt_live RT Σ) (rt_frames RT Σ) usp [(dat, dat + rs)] m mf pix v cv AGF) end;
    [ let e := fresh "e" in let He := fresh "He" in intros e He; exact He
    | exact (conj POBJ (conj D1 (conj DNZ R0)))
